81	            Color = Color.White,
82	            Target = RenderTargetID.UI,
83	            LayerDepth = _layers.GetDepth(GameDrawLayer.DialogueUI),
84	            NinePatchData = new NinePatchInfo(
85	                23,
86	                new Rectangle(0, 0, 23, 23),
87	                new Rectangle(23, 0, 1, 23),
88	                new Rectangle(24, 0, 23, 23),
89	                new Rectangle(0, 23, 23, 1),
90	                new Rectangle(23, 23, 1, 1),
91	                new Rectangle(24, 23, 23, 1),
92	                new Rectangle(0, 24, 23, 23),
93	                new Rectangle(23, 24, 1, 23),
94	                new Rectangle(24, 24, 23, 23))
95	        });
96	        _dialogueState.BoxEntity.Set(new DrawComponent
97	        {
98	            Type = DrawElementType.Sprite,
99	            Target = RenderTargetID.UI
100	        });
101	
102	        // Create text child entity
103	        _dialogueState.TextEntity = world.CreateEntity();
104	        _dialogueState.TextEntity.Set(new EntityInfo(nameof(EntityType.Interface), "DialogueText"));
105	        _dialogueState.TextEntity.Set(new Transform(textOffset));
106	        _dialogueState.TextEntity.SetParent(_rootEntity);
107	        _dialogueState.TextEntity.Set(new DynamicText
108	        {
109	            Target = RenderTargetID.UI,
110	            LayerDepth = _layers.GetDepth(GameDrawLayer.DialogueUI, +0.01f),
111	            Font = _font,
112	            Color = Color.SaddleBrown,
113	            Scale = 0.5f,
114	            RevealingSpeed = 20,
115	            RevealStartTime = float.NaN,
116	            IsRevealed = false,
117	            VisibleCharacterCount = 0,
118	            TextContent = ""
119	        });
120	        _dialogueState.TextEntity.Set(new DrawComponent
121	        {
122	            Type = DrawElementType.Text,
123	            Target = RenderTargetID.UI
124	        });
125	
126	        // Create indicator child entity
127	        _dialogueState.IndicatorEntity = world.CreateEntity();
128	        _dialogueState.IndicatorEntity.Set(new EntityInfo(nameof(EntityType.Interface), "DialogueIndicator"));
129	        _dialogueState.IndicatorEntity.Set(new Transform(indicatorOffset));
130	        _dialogueState.IndicatorEntity.SetParent(_rootEntity);
131	        _dialogueState.IndicatorEntity.Set(new SpriteInfo
132	        {
133	            SpriteSheet = indicatorTexture,
134	            Source = new Rectangle(0, 0, indicatorTexture.Width, indicatorTexture.Height),
135	            Size = new Vector2(16, 16),
136	            Color = Color.White,
137	            Target = RenderTargetID.UI,
138	            LayerDepth = _layers.GetDepth(GameDrawLayer.DialogueUI, +0.01f)
139	        });
140	        _dialogueState.IndicatorEntity.Set(new DrawComponent
141	        {
142	            Type = DrawElementType.Sprite,
143	            Target = RenderTargetID.UI
144	        });
145	
146	        // Set up Yarn runtime
147	        var paths = dialogueContentPaths ?? new[] { "Dialogues/hello_world" };
148	        _dialogueRunner = new DialogueRunner();
149	        _variableStorage = new InMemoryVariableStorage();
150	        _yarnDialogue = new Yarn.Dialogue(_variableStorage)
151	        {
152	            LogDebugMessage = msg => global::System.Diagnostics.Debug.WriteLine($"[Yarn] {msg}"),
153	            LogErrorMessage = msg => global::System.Diagnostics.Debug.WriteLine($"[Yarn ERROR] {msg}"),
154	            LineHandler = OnYarnLine,
155	            OptionsHandler = OnYarnOptions,
156	            CommandHandler = OnYarnCommand,
157	            NodeStartHandler = OnYarnNodeStart,
158	            NodeCompleteHandler = OnYarnNodeComplete,
159	            DialogueCompleteHandler = OnYarnDialogueComplete,
160	        };
161	
162	        // Load all yarn programs and combine via protobuf merge
163	        Yarn.Program combinedProgram = null;
164	        foreach (var path in paths)
165	        {
166	            var yarnProgram = content.Load<YarnProgram>(path);
167	            _dialogueRunner.AddStringTable(yarnProgram);
168	            var program = yarnProgram.GetProgram();
169	            if (combinedProgram == null)
170	            {
171	                combinedProgram = program;
172	            }
173	            else
174	            {
175	                combinedProgram.MergeFrom(program);
176	            }
177	        }
178	        _yarnDialogue.SetProgram(combinedProgram);
179	    }
180	
181	    // --- Yarn callbacks (fire synchronously during Continue()) ---
182	
183	    private void OnYarnLine(Line line)
184	    {
185	        var text = _dialogueRunner.GetLocalizedTextForLine(line);
186	
187	        // Parse "Speaker: text" format
188	        string? speaker = null;
189	        var displayText = text;
190	        var colonIndex = text.IndexOf(':');
191	        if (colonIndex > 0 && colonIndex < 30)
192	        {
193	            speaker = text[..colonIndex].Trim();
194	            displayText = text[(colonIndex + 1)..].Trim();
195	        }
196	
197	        _dialogueState.CurrentPhase = DialoguePhase.Line;
198	        _dialogueState.CurrentSpeaker = speaker;
199	        _dialogueState.WaitingForInput = false;
200	
201	        // Set text content and reset reveal animation
202	        ref var dynamicText = ref _dialogueState.TextEntity.Get<DynamicText>();
203	        dynamicText.TextContent = displayText;
204	        dynamicText.VisibleCharacterCount = 0;
205	        dynamicText.IsRevealed = false;
206	        dynamicText.RevealStartTime = float.NaN;
207	
208	        HideIndicator();
209	        HideOptions();
210	    }
211	
212	    private void OnYarnOptions(OptionSet optionSet)
213	    {
214	        _dialogueState.CurrentPhase = DialoguePhase.Options;
215	        _dialogueState.CurrentOptions.Clear();
216	        _dialogueState.CurrentOptionIDs.Clear();
217	        _dialogueState.SelectedOptionIndex = 0;
218	        _dialogueState.WaitingForInput = true;
219	
220	        foreach (var option in optionSet.Options)
221	        {
222	            if (!option.IsAvailable) continue;
223	            var text = _dialogueRunner.GetLocalizedTextForLine(option.Line);
224	            _dialogueState.CurrentOptions.Add(text);
225	            _dialogueState.CurrentOptionIDs.Add(option.ID);
226	        }
227	
228	        // Clear the main text line
229	        ref var dynamicText = ref _dialogueState.TextEntity.Get<DynamicText>();
230	        dynamicText.TextContent = "";
231	        dynamicText.VisibleCharacterCount = 0;
232	
233	        ShowOptions();
234	        HideIndicator();
235	    }
236	
237	    private void OnYarnCommand(Command command)
238	    {
239	        global::System.Diagnostics.Debug.WriteLine($"[Yarn Command] {command.Text}");
240	    }
241	
242	    private void OnYarnNodeStart(string nodeName)
243	    {
244	        global::System.Diagnostics.Debug.WriteLine($"[Yarn] Node started: {nodeName}");
245	    }
246	
247	    private void OnYarnNodeComplete(string nodeName)
248	    {
249	        global::System.Diagnostics.Debug.WriteLine($"[Yarn] Node complete: {nodeName}");
250	    }
251	
252	    private void OnYarnDialogueComplete()
253	    {
254	        _dialogueState.CurrentPhase = DialoguePhase.Complete;
255	        DeactivateDialogue();
256	    }
257	
258	    // --- Dialogue start trigger (from NPCInteractionSystem) ---
259	
260	    [Subscribe]
261	    private void OnDialogueStart(in DialogueStartMessage message)
262	    {
263	        if (_dialogueState.IsActive) return;
264	        StartYarnDialogue(message.StartNode);
265	    }
266	
267	    // --- Collision trigger ---
268	
269	    [Subscribe]
270	    private void OnCollision(in CollisionMessage message)
271	    {
272	        if (message.Type != CollisionType.Dialogue) return;
273	        if (_dialogueState.IsActive || _dialogueState.WasTriggered) return;
274	
275	        var zoneEntity = message.CollidingEntity;
276	        var nodeName = "HelloWorld";
277	
278	        if (zoneEntity.Has<DialogueZoneComponent>())
279	        {
280	            var zone = zoneEntity.Get<DialogueZoneComponent>();
281	            if (zone.OneTimeOnly && zone.HasBeenTriggered) return;
282	            nodeName = zone.YarnNodeName;
283	            zone.HasBeenTriggered = true;
284	        }
285	
286	        StartYarnDialogue(nodeName);
287	    }
288	
289	    public void StartYarnDialogue(string nodeName)
290	    {
291	        _dialogueState.IsActive = true;
292	        _dialogueState.WasTriggered = true;
293	        // The Interact press that opened this dialogue is still held — mark it as
294	        // held so the same press doesn't immediately advance the first line.
295	        _dialogueState.InteractHeld = true;
296	        _dialogueState.UpHeld = false;
297	        _dialogueState.DownHeld = false;
298	
299	        // Show dialogue box
300	        _dialogueState.BoxEntity.Set<Visible>();
301	
302	        _world.Publish(new DialogueActiveMessage(true));
303	
304	        // Start the yarn node — fires LineHandler or OptionsHandler synchronously
305	        _yarnDialogue.SetNode(nodeName);
306	        _yarnDialogue.Continue();
307	    }
308	
309	    // --- Update loop ---
310	
311	    public void Update(GameState state)
312	    {
313	        if (!_dialogueState.IsActive) return;
314	
315	        var interactNow = InputState.Interact.Pressed(state);
316	        var upNow = InputState.Up.Pressed(state);
317	        var downNow = InputState.Down.Pressed(state);
318	
319	        var interactJustPressed = interactNow && !_dialogueState.InteractHeld;
320	        var upJustPressed = upNow && !_dialogueState.UpHeld;
321	        var downJustPressed = downNow && !_dialogueState.DownHeld;
322	
323	        switch (_dialogueState.CurrentPhase)
324	        {
325	            case DialoguePhase.Line:
326	                UpdateLinePhase(interactJustPressed);
327	                break;
328	            case DialoguePhase.Options:
329	                UpdateOptionsPhase(upJustPressed, downJustPressed, interactJustPressed);
330	                break;
331	        }
332	
333	        _dialogueState.InteractHeld = interactNow;
334	        _dialogueState.UpHeld = upNow;
335	        _dialogueState.DownHeld = downNow;
336	    }
337	
338	    private void UpdateLinePhase(bool interactJustPressed)
339	    {
340	        ref var dynamicText = ref _dialogueState.TextEntity.Get<DynamicText>();
341	
342	        if (dynamicText.IsRevealed)
343	        {
344	            if (!_dialogueState.IndicatorEntity.Has<Visible>())
345	                _dialogueState.IndicatorEntity.Set<Visible>();
346	            _dialogueState.WaitingForInput = true;
347	        }
348	        else
349	        {
350	            HideIndicator();
351	        }
352	
353	        if (!interactJustPressed) return;
354	
355	        if (!dynamicText.IsRevealed)
356	        {
357	            // Skip reveal — show all text immediately
358	            dynamicText.VisibleCharacterCount = dynamicText.TextContent?.Length ?? 0;
359	            dynamicText.IsRevealed = true;
360	        }
361	        else
362	        {
363	            // Advance to next yarn content
364	            _yarnDialogue.Continue();
365	        }
366	    }
367	
368	    private void UpdateOptionsPhase(bool upJustPressed, bool downJustPressed, bool interactJustPressed)
369	    {
370	        if (upJustPressed)
371	        {
372	            _dialogueState.SelectedOptionIndex =
373	                Math.Max(0, _dialogueState.SelectedOptionIndex - 1);
374	            UpdateOptionHighlights();
375	        }
376	        else if (downJustPressed)
377	        {
378	            _dialogueState.SelectedOptionIndex =
379	                Math.Min(_dialogueState.CurrentOptions.Count - 1, _dialogueState.SelectedOptionIndex + 1);
380	            UpdateOptionHighlights();
381	        }
382	
383	        if (interactJustPressed)
384	        {
385	            var yarnOptionID = _dialogueState.CurrentOptionIDs[_dialogueState.SelectedOptionIndex];
386	            HideOptions();
387	            _yarnDialogue.SetSelectedOption(yarnOptionID);
388	            _yarnDialogue.Continue();
389	        }
390	    }
391	
392	    // --- Option entity management ---
393	
394	    private void ShowOptions()
395	    {
396	        HideOptions();
397	
398	        const float startY = 16f;
399	        const float optionSpacing = 24f;
400	
401	        for (var i = 0; i < _dialogueState.CurrentOptions.Count; i++)
402	        {
403	            var prefix = i == _dialogueState.SelectedOptionIndex ? "> " : "  ";
404	            var fullText = prefix + _dialogueState.CurrentOptions[i];
405	
406	            var optionEntity = _world.CreateEntity();
407	            optionEntity.Set(new EntityInfo(nameof(EntityType.Interface), $"DialogueOption{i}"));
408	            optionEntity.Set(new Transform(new Vector2(16, startY + i * optionSpacing)));
409	            optionEntity.SetParent(_rootEntity);
410	            optionEntity.Set(new DynamicText
411	            {
412	                Target = RenderTargetID.UI,
413	                LayerDepth = _layers.GetDepth(GameDrawLayer.DialogueUI, +0.01f),
414	                Font = _font,
415	                Color = i == _dialogueState.SelectedOptionIndex ? Color.White : Color.SaddleBrown,
416	                Scale = 0.5f,
417	                RevealingSpeed = 0, // Instant reveal
418	                RevealStartTime = 0,
419	                IsRevealed = true,
420	                VisibleCharacterCount = fullText.Length,
421	                TextContent = fullText
422	            });
423	            optionEntity.Set(new DrawComponent
424	            {
425	                Type = DrawElementType.Text,
426	                Target = RenderTargetID.UI
427	            });
428	            optionEntity.Set<Visible>();
429	
430	            _dialogueState.OptionEntities.Add(optionEntity);
431	        }
432	    }
433	
434	    private void UpdateOptionHighlights()
435	    {
436	        for (var i = 0; i < _dialogueState.OptionEntities.Count; i++)
437	        {
438	            var entity = _dialogueState.OptionEntities[i];
439	            if (!entity.IsAlive) continue;
440	
441	            ref var dt = ref entity.Get<DynamicText>();
442	            var prefix = i == _dialogueState.SelectedOptionIndex ? "> " : "  ";
443	            dt.TextContent = prefix + _dialogueState.CurrentOptions[i];
444	            dt.VisibleCharacterCount = dt.TextContent.Length;
445	            dt.Color = i == _dialogueState.SelectedOptionIndex ? Color.White : Color.SaddleBrown;
446	        }
447	    }
448	
449	    private void HideOptions()
450	    {
451	        foreach (var entity in _dialogueState.OptionEntities)
452	        {
453	            if (entity.IsAlive) entity.Dispose();
454	        }
455	        _dialogueState.OptionEntities.Clear();
456	    }
457	
458	    private void HideIndicator()
459	    {
460	        if (_dialogueState.IndicatorEntity.Has<Visible>())
461	            _dialogueState.IndicatorEntity.Remove<Visible>();
462	    }
463	
464	    // --- Deactivation ---
465	
466	    private void DeactivateDialogue()
467	    {
468	        _dialogueState.IsActive = false;
469	        _dialogueState.WasTriggered = false;
470	        _dialogueState.CurrentPhase = DialoguePhase.None;
471	        _dialogueState.WaitingForInput = false;
472	        _dialogueState.CurrentSpeaker = null;
473	
474	        HideOptions();
475	
476	        // Hide box
477	        if (_dialogueState.BoxEntity.Has<Visible>())
478	            _dialogueState.BoxEntity.Remove<Visible>();
479	
480	        var boxDraw = _dialogueState.BoxEntity.Get<DrawComponent>();
481	        boxDraw.Texture = null;
482	
483	        // Clear text
484	        ref var dynamicText = ref _dialogueState.TextEntity.Get<DynamicText>();
485	        dynamicText.VisibleCharacterCount = 0;
486	        dynamicText.IsRevealed = false;
487	        dynamicText.TextContent = "";
488	
489	        var textDraw = _dialogueState.TextEntity.Get<DrawComponent>();
490	        textDraw.Text = null;
491	        textDraw.Font = null;
492	
493	        // Hide indicator
494	        HideIndicator();
495	        var indicatorDraw = _dialogueState.IndicatorEntity.Get<DrawComponent>();
496	        indicatorDraw.Texture = null;
497	
498	        _world.Publish(new DialogueActiveMessage(false));
499	    }
500	
501	    public void Dispose()
502	    {
503	        GC.SuppressFinalize(this);
504	    }
505	}
